tool_input.command:
mkdir -p "$TMPDIR/scratch" && cd "$TMPDIR/scratch" && cat > Explore.java <<'EOF'
import java.util.Locale;
import java.util.Arrays;

public class Explore {
    public static void main(String[] args) {
        p("ROOT.toLanguageTag", Locale.ROOT.toLanguageTag());
        p("en.toLanguageTag", Locale.ENGLISH.toLanguageTag());
        Locale empty = new Locale("", "");
        p("empty.toLanguageTag", empty.toLanguageTag());
        p("ISOCountries contains EN", Arrays.asList(Locale.getISOCountries()).contains("EN"));
        p("ISOCountries contains US", Arrays.asList(Locale.getISOCountries()).contains("US"));
        p("ISOCountries contains GB", Arrays.asList(Locale.getISOCountries()).contains("GB"));
        Locale l = new Locale("fr", "CA", "xxx");
        p("fr_CA_xxx toString", l.toString());
        p("getAvailableLocales length", Locale.getAvailableLocales().length);
        try {
            Locale bad = new Locale("", null);
            p("new Locale('', null)", bad.toString());
        } catch (Exception e) {
            p("new Locale('', null) threw", e.getClass().getName());
        }
        try {
            Locale bad2 = new Locale(null, "US");
            p("new Locale(null,'US')", bad2.toString());
        } catch (Exception e) {
            p("new Locale(null,'US') threw", e.getClass().getName());
        }
    }
    static void p(String label, Object val) {
        System.out.println(label + " = " + val);
    }
}
EOF
javac Explore.java && java Explore
